global_css:
/* UptimeFixer remote safe overrides */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }
.ufx-safe-footer {
  background: #10202d;
  color: #f7fbff;
  font-family: inherit;
  border-top: 1px solid rgba(255,255,255,.08);
}
.ufx-safe-footer__inner {
  width: min(1280px, calc(100% - 48px));
  margin: 0 auto;
  padding: 64px 0 22px;
}
.ufx-safe-footer__main {
  display: grid;
  grid-template-columns: minmax(320px, 1.15fr) minmax(520px, 1.85fr);
  gap: 72px;
  align-items: start;
}
.ufx-safe-footer__brand { max-width: 430px; }
.ufx-safe-footer__logo {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  min-height: 64px;
  margin-bottom: 30px;
  text-decoration: none;
}
.ufx-safe-footer__logo img {
  display: block;
  width: auto;
  max-width: 245px;
  max-height: 72px;
  height: auto;
  object-fit: contain;
  background: #fff;
  padding: 10px 14px;
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(0,0,0,.12);
}
.ufx-safe-footer__eyebrow {
  margin: 0 0 12px;
  color: #c9f45b;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .14em;
}
.ufx-safe-footer__brand h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(38px, 4vw, 58px);
  line-height: .98;
  letter-spacing: -.045em;
  font-weight: 700;
}
.ufx-safe-footer__brand h2 span { color: #d9f78f; }
.ufx-safe-footer__intro {
  max-width: 390px;
  margin: 24px 0 0;
  color: rgba(237,244,250,.72);
  font-size: 17px;
  line-height: 1.7;
}
.ufx-safe-footer__cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 28px;
  padding: 13px 18px;
  border-radius: 999px;
  background: #c9f45b;
  color: #10202d !important;
  text-decoration: none !important;
  font-size: 14px;
  font-weight: 700;
  transition: transform .2s ease, background .2s ease;
}
.ufx-safe-footer__cta:hover { transform: translateY(-2px); background: #d7fb73; }
.ufx-safe-footer__nav {
  display: grid;
  grid-template-columns: 1.2fr .9fr .9fr;
  gap: 46px;
}
.ufx-safe-footer__nav section { min-width: 0; }
.ufx-safe-footer__nav h3 {
  margin: 7px 0 20px;
  color: #fff;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.ufx-safe-footer__nav ul { list-style: none; margin: 0; padding: 0; }
.ufx-safe-footer__nav li { margin: 0 0 13px; }
.ufx-safe-footer__nav a {
  color: rgba(235,242,248,.74);
  text-decoration: none;
  font-size: 15px;
  line-height: 1.45;
  transition: color .18s ease;
}
.ufx-safe-footer__nav a:hover { color: #c9f45b; }
.ufx-safe-footer__bottom {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 24px;
  align-items: center;
  margin-top: 54px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,.10);
}
.ufx-safe-footer__bottom p {
  margin: 0;
  color: rgba(231,239,246,.62);
  font-size: 13px;
  line-height: 1.5;
}
.ufx-safe-footer__bottom p:nth-child(2) { text-align: center; }
.ufx-safe-footer__bottom p:last-child { text-align: right; }
.ufx-safe-footer__bottom a { color: #6ba5ff; text-decoration: none; font-weight: 600; }
.ufx-safe-footer__bottom a:hover { color: #c9f45b; }
.ufx-safe-footer__heart { color: #ff5b64; }
@media (max-width: 1050px) {
  .ufx-safe-footer__main { grid-template-columns: 1fr; gap: 48px; }
  .ufx-safe-footer__brand { max-width: 640px; }
  .ufx-safe-footer__nav { grid-template-columns: repeat(3,1fr); }
  .ufx-safe-footer__bottom { grid-template-columns: 1fr; gap: 8px; }
  .ufx-safe-footer__bottom p,
  .ufx-safe-footer__bottom p:nth-child(2),
  .ufx-safe-footer__bottom p:last-child { text-align: left; }
}
@media (max-width: 680px) {
  .ufx-safe-footer__inner { width: min(100% - 32px, 1280px); padding-top: 48px; }
  .ufx-safe-footer__main { gap: 38px; }
  .ufx-safe-footer__nav { grid-template-columns: 1fr 1fr; gap: 32px 24px; }
  .ufx-safe-footer__nav section:first-child { grid-column: 1 / -1; }
  .ufx-safe-footer__nav section:first-child ul { columns: 2; column-gap: 28px; }
  .ufx-safe-footer__brand h2 { font-size: 40px; }
  .ufx-safe-footer__intro { font-size: 16px; }
  .ufx-safe-footer__logo img { max-width: 215px; }
  .ufx-safe-footer__bottom { margin-top: 42px; }
}
@media (max-width: 420px) {
  .ufx-safe-footer__nav { grid-template-columns: 1fr; }
  .ufx-safe-footer__nav section:first-child { grid-column: auto; }
  .ufx-safe-footer__nav section:first-child ul { columns: 1; }
}
